CREATE TABLE attachments(id INTEGER PRIMARY KEY AUTOINCREMENT,card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE,author_id INTEGER NOT NULL DEFAULT 0,name TEXT NOT NULL,mime TEXT NOT NULL,data_base64 TEXT NOT NULL,size INTEGER NOT NULL CHECK(size BETWEEN 0 AND 1048576),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),deleted_at TEXT);
INSERT INTO "attachments" VALUES(1,1,0,'legacy.txt','text/plain','bGVnYWN5LWNvbnRlbnQ=',14,'2026-10-16T05:45:35.068Z',NULL);
CREATE TABLE board_members(board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('admin','member','observer')),PRIMARY KEY(board_id,user_id));
CREATE TABLE board_watches(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,PRIMARY KEY(user_id,board_id));
CREATE TABLE boards(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',color TEXT NOT NULL DEFAULT 'sage',starred INTEGER NOT NULL DEFAULT 0 CHECK(starred IN(0,1)), created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
INSERT INTO "boards" VALUES(1,'Migrazione da OpenBoard 0.3','','sage',0,'2026-10-16T05:45:35.062Z','2026-10-16T05:45:35.068Z',5,NULL,0);
CREATE TABLE card_assignees(card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(card_id,user_id));
CREATE TABLE card_dependencies(card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE,required_card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE,CHECK(card_id<>required_card_id),PRIMARY KEY(card_id,required_card_id));
CREATE TABLE card_watches(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE,PRIMARY KEY(user_id,card_id));
CREATE TABLE cards(id INTEGER PRIMARY KEY AUTOINCREMENT,column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',label TEXT NOT NULL DEFAULT '',due_date TEXT NOT NULL DEFAULT '',assignee TEXT NOT NULL DEFAULT '',cover TEXT NOT NULL DEFAULT '',position INTEGER NOT NULL,completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN(0,1)),checklist TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(checklist)), created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN('low','normal','high','urgent')), labels TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(labels)), estimate_minutes INTEGER NOT NULL DEFAULT 0 CHECK(estimate_minutes BETWEEN 0 AND 100000), start_date TEXT NOT NULL DEFAULT '', blocked_reason TEXT NOT NULL DEFAULT '', actual_minutes INTEGER NOT NULL DEFAULT 0 CHECK(actual_minutes BETWEEN 0 AND 1000000), reference_url TEXT NOT NULL DEFAULT '');
INSERT INTO "cards" VALUES(1,1,'Dati da conservare','Contenuto precedente','design','2026-11-01','','',0,0,'[{"id":"legacy-item","text":"Non perdere questa voce","done":true}]','2026-10-16T05:45:35.066Z','2026-10-16T05:45:35.066Z',1,NULL,0,'normal','["design","sviluppo"]',0,'2026-10-16','',12,'');
CREATE TABLE columns(id INTEGER PRIMARY KEY AUTOINCREMENT,board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,title TEXT NOT NULL,position INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, deleted_at TEXT, wip_limit INTEGER NOT NULL DEFAULT 0 CHECK(wip_limit BETWEEN 0 AND 100000));
INSERT INTO "columns" VALUES(1,1,'Da fare',0,'2026-10-16T05:45:35.062Z','2026-10-16T05:45:35.062Z',1,NULL,0);
INSERT INTO "columns" VALUES(2,1,'In corso',1,'2026-10-16T05:45:35.062Z','2026-10-16T05:45:35.062Z',1,NULL,0);
INSERT INTO "columns" VALUES(3,1,'Completato',2,'2026-10-16T05:45:35.062Z','2026-10-16T05:45:35.062Z',1,NULL,0);
CREATE TABLE comments(id INTEGER PRIMARY KEY AUTOINCREMENT,card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE,author_id INTEGER NOT NULL DEFAULT 0,author TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), version INTEGER NOT NULL DEFAULT 1, edited_at TEXT);
INSERT INTO "comments" VALUES(1,1,0,'Locale','Commento precedente alla 0.4','2026-10-16T05:45:35.067Z',1,NULL);
CREATE TABLE idempotency(user_id INTEGER NOT NULL,path TEXT NOT NULL,key TEXT NOT NULL,request_body TEXT NOT NULL,status INTEGER NOT NULL,response_body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(user_id,path,key));
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO "metadata" VALUES('initialized','1');
CREATE TABLE notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,activity_id INTEGER NOT NULL REFERENCES activity(id) ON DELETE CASCADE,read_at TEXT,UNIQUE(user_id,activity_id));
CREATE TABLE saved_views(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL DEFAULT 0,board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,name TEXT NOT NULL,filters TEXT NOT NULL CHECK(json_valid(filters)),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
INSERT INTO "saved_views" VALUES(1,0,1,'Filtro storico','{"label":"design"}','2026-10-16T05:45:35.069Z');
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,csrf TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,created_at INTEGER NOT NULL, public_id TEXT NOT NULL DEFAULT '');
CREATE TABLE templates(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER NOT NULL DEFAULT 0,kind TEXT NOT NULL CHECK(kind IN('cards','boards')),name TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
INSERT INTO "templates" VALUES(1,0,'cards','Modello storico','{"title":"Dati da conservare","description":"Contenuto precedente","label":"design","labels":["design","sviluppo"],"due_date":"2026-11-01","assignee":"","cover":"","completed":false,"checklist":[{"id":"legacy-item","text":"Non perdere questa voce","done":true}],"priority":"normal","estimate_minutes":0,"start_date":"2026-10-16","blocked_reason":"","actual_minutes":12,"reference_url":""}','2026-10-16T05:45:35.069Z');
CREATE TABLE user_stars(board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(board_id,user_id));
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,username TEXT NOT NULL COLLATE NOCASE UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member' CHECK(role IN('admin','member','observer')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX columns_board ON columns(board_id,position);
CREATE INDEX cards_column ON cards(column_id,position);
CREATE TRIGGER boards_timestamps_insert AFTER INSERT ON boards BEGIN UPDATE boards SET created_at=CASE WHEN NEW.created_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.created_at END,updated_at=CASE WHEN NEW.updated_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.updated_at END WHERE id=NEW.id; END;
CREATE TRIGGER boards_timestamps_update AFTER UPDATE ON boards WHEN NEW.version=OLD.version AND NEW.created_at=OLD.created_at BEGIN UPDATE boards SET version=OLD.version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TRIGGER columns_timestamps_insert AFTER INSERT ON columns BEGIN UPDATE columns SET created_at=CASE WHEN NEW.created_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.created_at END,updated_at=CASE WHEN NEW.updated_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.updated_at END WHERE id=NEW.id; END;
CREATE TRIGGER columns_timestamps_update AFTER UPDATE ON columns WHEN NEW.version=OLD.version AND NEW.created_at=OLD.created_at BEGIN UPDATE columns SET version=OLD.version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TRIGGER cards_timestamps_insert AFTER INSERT ON cards BEGIN UPDATE cards SET created_at=CASE WHEN NEW.created_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.created_at END,updated_at=CASE WHEN NEW.updated_at='' THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE NEW.updated_at END WHERE id=NEW.id; END;
CREATE TRIGGER cards_timestamps_update AFTER UPDATE ON cards WHEN NEW.version=OLD.version AND NEW.created_at=OLD.created_at BEGIN UPDATE cards SET version=OLD.version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE INDEX comments_card ON comments(card_id,id);
CREATE INDEX activity_board ON activity(board_id,id DESC);
CREATE INDEX cards_due ON cards(due_date) WHERE deleted_at IS NULL;
CREATE INDEX cards_active ON cards(column_id,archived,position) WHERE deleted_at IS NULL;
CREATE INDEX boards_active ON boards(archived,id) WHERE deleted_at IS NULL;
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX board_members_user ON board_members(user_id,board_id);
CREATE INDEX assignees_user ON card_assignees(user_id,card_id);
CREATE INDEX dependencies_required ON card_dependencies(required_card_id,card_id);
CREATE INDEX templates_owner ON templates(owner_id,kind,id);
CREATE INDEX saved_views_owner ON saved_views(user_id,board_id,id);
CREATE INDEX card_watches_card ON card_watches(card_id,user_id);
CREATE INDEX board_watches_board ON board_watches(board_id,user_id);
CREATE INDEX notifications_user ON notifications(user_id,id DESC);
CREATE TRIGGER activity_notifications AFTER INSERT ON activity BEGIN INSERT OR IGNORE INTO notifications(user_id,activity_id) SELECT DISTINCT u.id,NEW.id FROM users u JOIN boards b ON b.id=NEW.board_id WHERE u.active=1 AND u.id<>NEW.actor_id AND b.deleted_at IS NULL AND (u.role='admin' OR EXISTS(SELECT 1 FROM board_members m WHERE m.board_id=NEW.board_id AND m.user_id=u.id)) AND (EXISTS(SELECT 1 FROM board_watches w WHERE w.user_id=u.id AND w.board_id=NEW.board_id) OR (NEW.entity_type='cards' AND EXISTS(SELECT 1 FROM card_watches w WHERE w.user_id=u.id AND w.card_id=NEW.entity_id)));END;
CREATE INDEX attachments_card ON attachments(card_id,id);
CREATE UNIQUE INDEX sessions_public ON sessions(public_id);
CREATE TRIGGER session_public_id AFTER INSERT ON sessions WHEN NEW.public_id='' BEGIN UPDATE sessions SET public_id=lower(hex(randomblob(16))) WHERE token_hash=NEW.token_hash;END;
CREATE VIEW ob_card_objects AS SELECT k.*,json_object('id',k.id,'column_id',k.column_id,'title',k.title,'description',k.description,'label',k.label,'labels',json(k.labels),'due_date',k.due_date,'assignee',k.assignee,'cover',k.cover,'position',k.position,'completed',json(CASE k.completed WHEN 1 THEN 'true' ELSE 'false' END),'checklist',json(k.checklist),'priority',k.priority,'estimate_minutes',k.estimate_minutes,'archived',json(CASE k.archived WHEN 1 THEN 'true' ELSE 'false' END),'version',k.version,'created_at',k.created_at,'updated_at',k.updated_at,'start_date',k.start_date,'blocked_reason',k.blocked_reason,'actual_minutes',k.actual_minutes,'reference_url',k.reference_url,'assignee_ids',json((SELECT json_group_array(user_id) FROM card_assignees WHERE card_id=k.id)),'assignees',json((SELECT json_group_array(json_object('id',u.id,'name',u.name,'username',u.username)) FROM card_assignees a JOIN users u ON u.id=a.user_id WHERE a.card_id=k.id))) data,json_object('id',k.id,'column_id',k.column_id,'title',k.title,'description_preview',substr(k.description,1,160),'checklist_total',json_array_length(k.checklist),'checklist_done',(SELECT count(*) FROM json_each(k.checklist) WHERE json_extract(value,'$.done')=1),'label',k.label,'labels',json(k.labels),'due_date',k.due_date,'assignee',k.assignee,'cover',k.cover,'position',k.position,'completed',json(CASE k.completed WHEN 1 THEN 'true' ELSE 'false' END),'priority',k.priority,'estimate_minutes',k.estimate_minutes,'archived',json(CASE k.archived WHEN 1 THEN 'true' ELSE 'false' END),'version',k.version,'created_at',k.created_at,'updated_at',k.updated_at,'start_date',k.start_date,'blocked_reason',k.blocked_reason,'actual_minutes',k.actual_minutes,'reference_url',k.reference_url,'assignee_ids',json((SELECT json_group_array(user_id) FROM card_assignees WHERE card_id=k.id)),'assignees',json((SELECT json_group_array(json_object('id',u.id,'name',u.name,'username',u.username)) FROM card_assignees a JOIN users u ON u.id=a.user_id WHERE a.card_id=k.id))) summary FROM cards k;
CREATE VIEW ob_board_objects AS SELECT b.*,json_object('id',b.id,'name',b.name,'description',b.description,'color',b.color,'starred',json(CASE ob_starred(b.id,b.starred) WHEN 1 THEN 'true' ELSE 'false' END),'archived',json(CASE b.archived WHEN 1 THEN 'true' ELSE 'false' END),'version',b.version,'created_at',b.created_at,'updated_at',b.updated_at,'role',ob_role(b.id),'membership_role',ob_role(b.id),'readonly',json(CASE ob_readonly(b.id) WHEN 1 THEN 'true' ELSE 'false' END),'columns',json((SELECT json_group_array(json(col)) FROM(SELECT json_object('id',c.id,'title',c.title,'position',c.position,'wip_limit',c.wip_limit,'version',c.version,'created_at',c.created_at,'updated_at',c.updated_at,'cards',json((SELECT json_group_array(json(item)) FROM(SELECT CASE ob_summary() WHEN 1 THEN k.summary ELSE k.data END item FROM ob_card_objects k WHERE k.column_id=c.id AND k.deleted_at IS NULL AND (ob_archived() OR k.archived=0) ORDER BY k.position,k.id)))) col FROM columns c WHERE c.board_id=b.id AND c.deleted_at IS NULL ORDER BY c.position,c.id)))) data FROM boards b;
DELETE FROM "sqlite_sequence";
INSERT INTO "sqlite_sequence" VALUES('boards',1);
INSERT INTO "sqlite_sequence" VALUES('columns',3);
INSERT INTO "sqlite_sequence" VALUES('notifications',0);
INSERT INTO "sqlite_sequence" VALUES('activity',4);
INSERT INTO "sqlite_sequence" VALUES('cards',1);
INSERT INTO "sqlite_sequence" VALUES('comments',1);
INSERT INTO "sqlite_sequence" VALUES('attachments',1);
INSERT INTO "sqlite_sequence" VALUES('saved_views',1);
INSERT INTO "sqlite_sequence" VALUES('templates',1);
COMMIT;
PRAGMA user_version=4;
